import { usePathname, useRouter } from "next/navigation";
import type { ChangeEvent, FormEvent, ReactNode } from "react";
import { ArrowDownRight, ArrowRight, CalendarDays, Check, CheckCircle2, ChevronDown, ClipboardCheck, CloudSun, FileSpreadsheet, Leaf, MessageCircle, MessageSquareText, Plus, Save, Send, Settings2, ShieldCheck, Sprout, TrendingUp, Users, Wheat, Wifi, WifiOff, Home, Map as MapIcon, UserRound, Truck, MapPin, PackageCheck, Globe2, Building2, FileText, Handshake } from "lucide-react";
import { Map as MapCN, MapControls, MapGeoJSON, MapMarker, MarkerContent, MarkerTooltip, useMap, MapRoute, RouteProgress, RouteMarker } from "@/components/ui/map";
