const paths: Record<View, string> = { overview: "/", demand: "/contracts", trade: "/trade", plan: "/plan", farmers: "/farmers", guidance: "/guidance", results: "/results", shipments: "/shipments", "farmer-home": "/farmer", "farmer-plan": "/farmer/plan", "farmer-guidance": "/farmer/guidance", "farmer-profile": "/farmer/profile" };
const pathToView: Record<string, View> = { "/": "overview", "/contracts": "demand", "/demand": "demand", "/trade": "trade", "/plan": "plan", "/farmers": "farmers", "/guidance": "guidance", "/results": "results", "/shipments": "shipments", "/farmer": "farmer-home", "/farmer/plan": "farmer-plan", "/farmer/guidance": "farmer-guidance", "/farmer/profile": "farmer-profile" };
